from pydantic import BaseModel, Field

class Paper(BaseModel):
    """One provided paper: its own title and which of the OTHER provided papers it references in its bibliography."""
    title: str | None = Field(description="This paper's full title")
    references_provided_papers: list[str] = Field(
        description="Titles of OTHER provided papers (known from document summaries) that appear in this paper's reference list"
    )

class Parse(BaseModel):
    papers: list[Paper]
